(7684123, 1257761, 52549, '<td valign="top">Many congrats, Susan. It''s a great take on the challenge, I love the textures and the lighting.</td>', 'Many congrats, Susan. It''s a great take on the challenge, I love the textures and the lighting.', '2021-01-11 05:27:16.000000', NULL, 0),
(7684124, 1257462, 52549, '<td valign="top">It is indeed a wonderful image. Really glad it did well for you. Congrats.</td>', 'It is indeed a wonderful image. Really glad it did well for you. Congrats.', '2021-01-11 05:28:47.000000', NULL, 0),
(7684125, 1257775, 143116, '<td valign="top">Thanks for the positive comments. This was taken in the huge Qianyue complex in Taichung, Taiwan. The challenge was a great inspiration to find out what abandoned buildings can be found around here, and I enjoyed it a lot.<br/> <br/>The pole behind the woman''s back is a piece of bamboo.</td>', 'Thanks for the positive comments. This was taken in the huge Qianyue complex in Taichung, Taiwan. The challenge was a great inspiration to find out what abandoned buildings can be found around here, and I enjoyed it a lot. The pole behind the woman''s back is a piece of bamboo.', '2021-01-11 07:20:34.000000', NULL, 0),
(7684126, 1257743, 114285, '<td valign="top">Vivid Lev!<br/> <br/>And that burst, brilliant!</td>', 'Vivid Lev! And that burst, brilliant!', '2021-01-11 07:51:20.000000', NULL, 0),
(7684127, 1257793, 114285, '<td valign="top">Loved the overgrowth!</td>', 'Loved the overgrowth!', '2021-01-11 07:52:10.000000', NULL, 0),
